   118|async function tick(): Promise<void> {
   119|  // ─── Orphan-task recovery ──────────────────────────────────────────
   120|  // If the worker restarts mid-loop (e.g. Render redeploy), a task can be
   121|  // left in RUNNING/TESTING with a stale heartbeat. Requeue any senior-dev
   122|  // task whose heartbeat is older than TASK_CLAIM_TIMEOUT_MS so it gets
   123|  // re-picked instead of sitting orphaned forever (root cause of the
   124|  // 20f65308 task stuck in TESTING for 26+ min across a restart).
   125|  try {
   126|    await recoverOrphanedTasks();
   127|  } catch (error) {
   128|    console.log('[IVX-SENIOR-DEV-01] Orphan recovery error (non-fatal):', error instanceof Error ? error.message : 'unknown');
   129|  }
   130|
   131|  const tasks = await listTasks(50);
   132|  const candidates = tasks.filter((t) => {
   133|    // Mark senior_dev tasks via trace_id (always "senior-dev-..." from the
   134|    // submit endpoint) because the task_type column is only created by the
   135|    // self-bootstrap DDL, which requires SUPABASE_ACCESS_TOKEN and may not have
   136|    // run yet. trace_id is in the original CREATE TABLE and is always present,
   137|    // so it is the reliable marker. task_type is checked too as a fallback.
   138|    const isSeniorDev = (t.task_type === 'senior_dev')
   139|      || (typeof t.trace_id === 'string' && t.trace_id.startsWith('senior-dev-'));
   140|    if (!isSeniorDev) return false;
   141|    if (t.status !== 'QUEUED' && t.status !== 'RETRYING') return false;
   142|    if (t.assigned_worker_id && t.assigned_worker_id !== IVX_SENIOR_DEV_WORKER_ID) return false;
   143|    return true;
   144|  });
   145|
   146|  if (candidates.length === 0) return;
   147|
   148|  const task = candidates.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())[0];
   149|  if (!task) return;
   150|
   151|  const claimed = await claimTask(task.id);
   152|  if (!claimed) return;
   153|
   154|  state.currentTaskId = task.id;
   155|  state.runCount += 1;
   156|
   157|  try {
   158|    await executeSeniorDevTask(claimed);
   159|  } catch (error) {
   160|    state.errorCount += 1;
   161|    console.log('[IVX-SENIOR-DEV-01] executeSeniorDevTask error:', error instanceof Error ? error.message : 'unknown');
   162|    await failTask(task.id, error instanceof Error ? error.message : 'unknown');
   163|  } finally {
   164|    state.currentTaskId = null;
   165|    state.currentPhase = null;
   166|  }
   167|}
