   169|async function recoverOrphanedTasks(): Promise<void> {
   170|  const tasks = await listTasks(100);
   171|  const now = Date.now();
   172|  const stale: IVXOwnerAITaskRow[] = [];
   173|  for (const t of tasks) {
   174|    const isSeniorDev = (t.task_type === 'senior_dev')
   175|      || (typeof t.trace_id === 'string' && t.trace_id.startsWith('senior-dev-'));
   176|    if (!isSeniorDev) continue;
   177|    if (t.status !== 'RUNNING' && t.status !== 'WAITING_APPROVAL' && t.status !== 'COMMITTING') continue;
   178|    // If the task already has a commit_sha, it did real work — the worker just
   179|    // got killed (likely by its own Render deploy restarting the runtime) before
   180|    // reaching VERIFIED. Mark it terminal FAILED with the real evidence it has,
   181|    // rather than re-running the whole pipeline (which would re-plan, re-implement,
   182|    // and either no-op or duplicate-commit). This also unblocks single-flight
   183|    // for the next queued task.
   184|    if (t.commit_sha) {
   185|      console.log('[IVX-SENIOR-DEV-01] Orphaned task already committed — marking terminal', { taskId: t.id, commitSha: t.commit_sha, status: t.status });
   186|      await patchTask(t.id, {
   187|        status: 'FAILED',
   188|        checkpoint: 'FAILED (orphaned after commit — worker killed by self-deploy restart before LIVE_VERIFYING)',
   189|        error_message: `Worker restarted mid-task after commit ${t.commit_sha}. The commit is real and on GitHub; the task just did not reach VERIFIED because the worker process was killed by its own Render deploy triggering a runtime restart. File(s) changed: ${JSON.stringify(t.files_changed ?? [])}.`,
   190|        checkpoint_history: appendCheckpoint(null, `ORPHAN_TERMINATED_WITH_COMMIT at ${new Date().toISOString()} (commitSha=${t.commit_sha})`),
   191|      });
   192|      continue;
   193|    }
   194|    const hb = t.heartbeat_at ? new Date(t.heartbeat_at).getTime() : 0;
   195|    if (now - hb > TASK_CLAIM_TIMEOUT_MS) stale.push(t);
   196|  }
   197|  for (const s of stale) {
   198|    console.log('[IVX-SENIOR-DEV-01] Requeuing orphaned task', { taskId: s.id, status: s.status, heartbeatAt: s.heartbeat_at });
   199|    await patchTask(s.id, {
   200|      status: 'RETRYING',
   201|      checkpoint: 'RETRYING (orphan recovered — stale heartbeat)',
   202|      checkpoint_history: appendCheckpoint(null, `ORPHAN_RECOVERED at ${new Date().toISOString()}`),
   203|    });
   204|  }
   205|}
