   207|async function claimTask(taskId: string): Promise<IVXOwnerAITaskRow | null> {
   208|  const now = new Date().toISOString();
   209|  // The submit endpoint pre-assigns assigned_worker_id='IVX-SENIOR-DEV-01' so the
   210|  // task is already bound to this worker. The optimistic claim must therefore
   211|  // accept rows where assigned_worker_id IS NULL (unassigned) OR already equals
   212|  // IVX-SENIOR-DEV-01 (pre-assigned to us). Using PostgREST or= syntax.
   213|  const filter = `&status=in.(QUEUED,RETRYING)&or=(assigned_worker_id.is.null,assigned_worker_id.eq.${encodeURIComponent(IVX_SENIOR_DEV_WORKER_ID)})`;
   214|  const patched = await patchTask(taskId, {
   215|    status: 'RUNNING',
   216|    checkpoint: `CLAIMED by ${IVX_SENIOR_DEV_WORKER_ID}`,
   217|    assigned_worker_id: IVX_SENIOR_DEV_WORKER_ID,
   218|    heartbeat_at: now,
   219|    checkpoint_history: appendCheckpoint(null, `CLAIMED by ${IVX_SENIOR_DEV_WORKER_ID} at ${now}`),
   220|  }, filter);
   221|  return patched;
   222|}
