const ownerAt = await Bun.file("/tmp/owner_at").text();
const ACTION_URL = "https://api.ivxholding.com/api/ivx/developer-deploy/action";

async function gzipBase64(path) {
  const content = await Bun.file(path).text();
  const tc = new TextEncoder().encode(content);
  const cs = new CompressionStream("gzip");
  const w = cs.writable.getWriter();
  w.write(tc); w.close();
  const chunks = [];
  const r = cs.readable.getReader();
  for (;;) { const { done, value } = await r.read(); if (done) break; chunks.push(value); }
  const gz = new Uint8Array(chunks.reduce((n, c) => n + c.length, 0));
  let o = 0; for (const c of chunks) { gz.set(c, o); o += c.length; }
  let bin = ""; for (let i = 0; i < gz.length; i++) bin += String.fromCharCode(gz[i]);
  return btoa(bin);
}

async function commitFile(path, msg, useGzip) {
  const content = useGzip ? await gzipBase64(path) : await Bun.file(path).text();
  const body = {
    action: "github_commit_file",
    input: { path, content, message: msg, ...(useGzip ? { contentEncoding: "gzip-base64" } : {}) },
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
  };
  const res = await fetch(ACTION_URL, {
    method: "POST",
    headers: { Authorization: `Bearer ${ownerAt}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const d = await res.json();
  const sha = d.result?.commitSha ?? d.result?.sha ?? null;
  const mode = d.result?.mode ?? d.result?.content?.path ? "new" : "update";
  console.log(`${path}: ${res.status} ok=${d.ok} sha=${(sha ?? "").slice(0,12)} mode=${mode} err=${(d.error ?? "").slice(0,100)}`);
  return { path, ok: d.ok === true, sha, error: d.error };
}

// server.ts is small (2577 bytes) — plain text. Others >30KB use gzip-base64.
const results = [];
results.push(await commitFile("server.ts", "IVX-SENIOR-DEV-01: Path B — wire recoverSelfDeployTasks into server.ts boot before startSeniorDevWorker", false));
results.push(await commitFile("backend/services/ivx-senior-dev-proof.ts", "IVX-SENIOR-DEV-01: Path B — add resume/lease columns + claimRecoveryLease/releaseRecoveryLease helpers", true));
results.push(await commitFile("backend/services/ivx-owner-ai-task-queue.ts", "IVX-SENIOR-DEV-01: Path B — extend IVXOwnerAITaskRow with resume/lease fields + listSelfDeployResumableTasks", true));
results.push(await commitFile("backend/services/ivx-enterprise-deployment-engine.ts", "IVX-SENIOR-DEV-01: Path B — add getRenderDeployCommitSha helper for 3-way SHA parity", true));
results.push(await commitFile("backend/services/ivx-senior-dev-self-deploy-recovery.ts", "IVX-SENIOR-DEV-01: Path B — NEW boot scanner recoverSelfDeployTasks with optimistic-lock lease + 3-way parity + live feature test", true));
results.push(await commitFile("backend/services/ivx-senior-dev-worker.ts", "IVX-SENIOR-DEV-01: Path B — rewrite DEPLOYING into handoff+clean-exit, add live feature test, enforce exactly-one-terminal-state", true));
results.push(await commitFile("backend/ivx-senior-dev-self-deploy-recovery.test.ts", "IVX-SENIOR-DEV-01: Path B — 14 regression tests for self-deploy handoff/recovery/parity/terminal", false));

const ok = results.filter(r => r.ok).length;
console.log(`\nCOMMITTED ${ok}/${results.length}`);
const lastSha = results.filter(r => r.sha).pop()?.sha ?? null;
console.log("LAST_SHA=" + (lastSha ?? "null"));
EOF
