  try { h1 = JSON.parse(txt); } catch (e) { console.log("PARSE_ERR=" + (e instanceof Error ? e.message : String(e))); }
  if (h1) {
    console.log("RUNTIME_SHA=" + h1.commit, "boot=" + h1.bootTime, "NOW=" + new Date().toISOString(), "status=" + h1.status);
  }
