    const r = await fetch("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/" + tid, {
      headers: { Authorization: "Bearer " + ownerAt },
    });
    const txt = await r.text();
    console.log("TASK " + tid.slice(0,8) + ": http=" + r.status, "bodyLen=" + txt.length, "bodyHead=" + txt.slice(0, 300));
  } catch (e) {
    console.log("TASK " + tid.slice(0,8) + " ERR=" + (e instanceof Error ? e.message : String(e)));
  }
}

