const ownerAt = await Bun.file("/tmp/owner_at").text();

// 1. Runtime state
const r1 = await fetch("https://api.ivxholding.com/health");
const h1 = await r1.json();
console.log("RUNTIME_SHA=" + h1.commit, "boot=" + h1.bootTime, "NOW=" + new Date().toISOString(), "status=" + h1.status);

// 2. Both tasks — full detail
for (const tid of ["0d4f09e5-8afb-43a8-9a8d-db522887813b", "7862343b-3253-4824-8b86-4d0969c9372e"]) {
  const r = await fetch("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/" + tid, {
    headers: { Authorization: "Bearer " + ownerAt },
  });
  const d = await r.json();
  const t = d.task ?? {};
  console.log("\nTASK " + tid.slice(0,8) + ":");
  console.log("  status=" + t.status + " terminal=" + t.terminal);
  console.log("  checkpoint=" + t.checkpoint);
  console.log("  commitSha=" + (t.commitSha ?? "null"));
  console.log("  proofLedgerId=" + (t.proofLedgerId ?? "null"));
  console.log("  renderDeployId=" + (t.renderDeployId ?? "null"));
  console.log("  runtimeSha=" + (t.runtimeSha ?? "null"));
  console.log("  filesChanged=" + JSON.stringify(t.filesChanged ?? []));
  console.log("  updatedAt=" + t.updatedAt);
  if (t.errorMessage) console.log("  error=" + String(t.errorMessage).slice(0, 500));
}

// 3. Worker status
const r3 = await fetch("https://api.ivxholding.com/api/ivx/senior-developer/worker/status", {
  headers: { Authorization: "Bearer " + ownerAt },
});
