const ownerAt = await Bun.file("/tmp/owner_at").text();

// 1. Runtime state
const r1 = await fetch("https://api.ivxholding.com/health");
const h1 = await r1.json();
console.log("RUNTIME_SHA=" + h1.commit, "boot=" + h1.bootTime, "NOW=" + new Date().toISOString(), "status=" + h1.status);

// 2. Check if Path B code is live by looking for the self-deploy-recovery module
// The worker status endpoint returns static info, but if Path B is live, the
// boot sequence would have logged "SelfDeployRecovery" messages. We can't read
// logs directly, but we CAN check: does the error message from 7862343b include
// "feature=" (Path B adds the live feature test to the fail reason)?
console.log("\n=== Checking if Path B is live (7862343b error message signature) ===");
const r2 = await fetch("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/7862343b-3253-4824-8b86-4d0969c9372e", {
  headers: { Authorization: "Bearer " + ownerAt },
});
const d2 = await r2.json();
const t2 = d2.task ?? {};
console.log("7862343b error: " + (t2.errorMessage ?? "null"));
console.log("Has 'feature=' in error: " + String(t2.errorMessage ?? "").includes("feature="));
console.log("→ If FALSE, OLD code ran (Path B NOT live). If TRUE, Path B ran.");

// 3. Both tasks
console.log("\n=== Task states ===");
for (const tid of ["0d4f09e5-8afb-43a8-9a8d-db522887813b", "7862343b-3253-4824-8b86-4d0969c9372e"]) {
  const r = await fetch("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/" + tid, {
    headers: { Authorization: "Bearer " + ownerAt },
  });
  const d = await r.json();
  const t = d.task ?? {};
  console.log("TASK " + tid.slice(0,8) + ": status=" + t.status + " terminal=" + t.terminal + " commitSha=" + (t.commitSha ?? "null").slice(0,12));
}

